$(() => {
  const 地区基础风险: Record<string, number> = {
    商业区: 70,
    老城区: 65,
    工业区: 45,
    住宅区: 40,
    公园: 25,
    地铁: 55,
    江城大学: 50,
  };
  const 醉汉地区 = ['住宅区', '商业区', '老城区', '公园'];
  const 小混混地区 = ['老城区', '工业区'];

  function 时段(小时: number): string {
    if (小时 >= 6 && 小时 < 9) return '早晨';
    if (小时 >= 9 && 小时 < 18) return '白天';
    if (小时 >= 18 && 小时 < 22) return '晚上';
    return '深夜';
  }

  function 是否露出(穿着: Record<string, string>, 束缚: Record<string, string>): boolean {
    const 关键穿着 = ['上衣', '下装', '胸罩', '内裤'];
    if (关键穿着.some(k => !穿着?.[k] || 穿着[k] === '无')) return true;
    const 显眼束缚 = ['眼部', '口部', '脚踝'];
    if (显眼束缚.some(k => 束缚?.[k] && 束缚[k] !== '无')) return true;
    return false;
  }

  function 注入事件(文本: string) {
    injectPrompts(
      [{ id: 'random_event', position: 'in_chat', depth: 0, role: 'system', content: 文本 }],
      { once: true },
    );
  }

  eventOn(tavern_events.GENERATION_STARTED, async () => {
    await waitGlobalInitialized('Mvu');
    if (Mvu.isDuringExtraAnalysis()) return;

    const data = Mvu.getMvuData({ type: 'message', message_id: 'latest' });
    const stat = _.get(data, 'stat_data');
    if (!stat) return;

    const 区域: string = stat.位置?.区域 ?? '';
    const 小时: number = Number(stat.时间?.小时 ?? 12);
    const 段 = 时段(小时);
    const 露出 = 是否露出(stat.穿着 ?? {}, stat.束缚 ?? {});
    const 性欲 = Number(stat.性欲值 ?? 0);

    // 天气：全局，任何时候可触发
    if (Math.random() < 0.05) {
      注入事件(
        '【随机事件·天气】天气发生了变化（如下雨、起风、降温等，由你随机选择一种，要符合当前时段）。请在正文中自然体现天气变化对江星晚的影响。',
      );
      return;
    }

    if (露出) {
      const 风险 = 地区基础风险[区域] ?? 40;
      let 概率 = 0.1 + 风险 * 0.002;
      if (段 === '深夜') 概率 += 0.05;
      if (性欲 > 80) 概率 += 0.05;

      if (Math.random() < 概率) {
        const 可小混混 = 小混混地区.includes(区域);
        const 可醉汉 = 醉汉地区.includes(区域);
        if (可小混混 && Math.random() < 0.5) {
          注入事件(
            '【随机事件·小混混】几个小混混在附近游荡，注意到了江星晚，不怀好意地靠了过来。请自然演绎这次冲突，对方可能勒索、动手，甚至把她带走。',
          );
        } else if (可醉汉) {
          注入事件(
            '【随机事件·醉汉】一个满身酒气的醉汉摇摇晃晃地朝江星晚这边走来，似乎注意到了她。请自然演绎这次偶遇。',
          );
        } else {
          注入事件(
            '【随机事件·路人】有路人注意到江星晚的异样，犹豫后上前询问她是否身体不适、需不需要帮忙。请自然演绎这次对话。',
          );
        }
        return;
      }

      // 路人询问：独立低概率
      if (Math.random() < 0.05) {
        注入事件(
          '【随机事件·路人】有路人注意到江星晚的异样举动，犹豫了一下，上前询问她是否身体不适、需不需要帮忙。请自然演绎这次对话。',
        );
        return;
      }

      // 丢钥匙：自缚时
      const 有束缚 = Object.values(stat.束缚 ?? {}).some((v: string) => v && v !== '无');
      if (有束缚 && Math.random() < 0.04) {
        注入事件(
          '【随机事件·丢钥匙】江星晚发现自己藏起的自缚钥匙不见了（或从身上掉落）。她此刻正被束缚着，必须找回钥匙才能解开。请自然演绎这份慌乱与失控。',
        );
        return;
      }
    }

    // 同好偶遇：平时/露出中都可
    if (Math.random() < 0.03) {
      const 顾鸢露出 = Math.random() < 0.3;
      if (!露出 && !顾鸢露出) {
        注入事件(
          '【随机事件·同好】江星晚偶然遇到了同好顾鸢，两人此刻都只是普通出门。请自然演绎这次偶遇，她们可能闲聊、交流心得。',
        );
      } else if (!露出 && 顾鸢露出) {
        注入事件(
          '【随机事件·同好】江星晚偶然撞见同好顾鸢正在某个隐蔽处玩自缚露出。请自然演绎这个尴尬又兴奋的场景。',
        );
      } else if (露出 && !顾鸢露出) {
        注入事件(
          '【随机事件·同好】江星晚正在露出时，被恰好路过的同好顾鸢撞见。请自然演绎顾鸢的反应——她大概会心照不宣地帮她望风或解围。',
        );
      } else {
        注入事件(
          '【随机事件·同好】江星晚正在露出时，遇到了同样在玩露出的顾鸢。两人相视会心一笑，可能一起继续这场游戏。请自然演绎。',
        );
      }
      return;
    }

    // 被闺蜜撞见：住宅区/校园
    if ((区域 === '住宅区' || 区域 === '江城大学') && Math.random() < 0.02) {
      注入事件(
        '【随机事件·闺蜜】江星晚的闺蜜林知夏恰好出现在附近，似乎注意到了她的异样。请自然演绎这个可能暴露秘密的时刻。',
      );
      return;
    }
  });
});
